{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "The closest analogue showed only 0.7% ID peak brain radioactivity in cynomolgus monkeys and was classified as low permeability/P-gp efflux substrate, providing contradictory evidence for CNS access.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "AZ10419369, a close analogue sharing the methylpiperazine-aryl amide and heteroaromatic/morpholine-like motif, reached 3–4% of injected radioactivity in macaque brain after IV injection, demonstrating meaningful CNS access in primates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A piperazine-amide analogue crossed the BBB in mice and was detected in brain 2 h after exposure, supporting CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "An analogue containing tetrahydropyran-amide and fluorophenyl motifs had a brain-to-plasma ratio of 1.29 in mice with good PK, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A morpholine-amide heteroaromatic analogue showed a Kp of 11.4 in mice with negligible P-gp efflux, supporting strong CNS penetration for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: despite a low passive-diffusion physicochemical prior and one closest low-uptake analogue, the preponderance of in vivo evidence from structurally related piperazine-amide/heteroaryl molecules shows meaningful brain uptake across rodents, primates, and humans, including high Kp and brain-to-plasma ratios.",
  "evidence_gaps": [
    "No direct experimental BBB data for the exact query molecule.",
    "All analogue similarities are low (<0.35), limiting quantitative transfer.",
    "Species-dependent efflux (rodent vs primate) complicates translation.",
    "No unbound brain/plasma or CSF exposure data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

